template:
// Count subarrays with sum exactly k. O(n) time, O(n) space.
int subarraySum(const vector<int>& a, int k) {
    unordered_map<long long, int> seen;   // prefix value -> how many times seen
    seen[0] = 1;                          // the empty prefix, so subarrays starting at 0 count
    long long prefix = 0;
    int count = 0;
    for (int x : a) {
        prefix += x;
        auto it = seen.find(prefix - k);  // earlier prefix that makes this range sum k
        if (it != seen.end()) count += it->second;
        seen[prefix]++;                   // record AFTER the lookup (l must be < r)
    }
    return count;
}

// Range-sum queries with no updates: build once, answer each in O(1).
vector<long long> buildPrefix(const vector<int>& a) {
    vector<long long> P(a.size() + 1, 0);
    for (size_t i = 0; i < a.size(); ++i) P[i + 1] = P[i] + a[i];
    return P;                             // sum(l..r) inclusive = P[r+1] - P[l]
}
